import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import '../css/MainPage.css';

export default function MainPage() {
    const [loading, setLoading] = useState(true);
    const [activeNav, setActiveNav] = useState('main');
    const navigate = useNavigate();

    // 인증 상태 확인
    useEffect(() => {
        fetch('http://localhost:4000/api/me', {
            method: 'GET',
            credentials: 'include',
        })
            .then(res => res.json())
            .then(data => {
                if (!data.loggedIn) {
                    navigate('/');
                } else {
                    setLoading(false);
                }
            })
            .catch(err => {
                console.error(err);
                navigate('/');
            });
    }, [navigate]);

    const handleCreateProject = () => {
        navigate('/project');
    };

    const handleLogout = () => {
        fetch('http://localhost:4000/api/logout', {
            method: 'POST',
            credentials: 'include',
        })
            .then(() => navigate('/'))
            .catch(err => {
                console.error(err);
                navigate('/');
            });
    };

    const navItems = [
        { key: 'main', label: '메인화면' },
        { key: 'projects', label: '프로젝트' },
        { key: 'vulnList', label: '취약점 정리' },
        { key: 'vulnEdu', label: '취약점 교육' },
        { key: 'tos', label: '개인정보 약관' },
    ];

    if (loading) {
        return <p className="loading">로딩 중…</p>;
    }

    return (
        <div className="app-container">
            {/* Sidebar */}
            <aside className="sidebar">
                <button className="create-btn" onClick={handleCreateProject}>
                    + 새 프로젝트 만들기
                </button>
                <nav className="nav-group">
                    {navItems.map(item => (
                        <div
                            key={item.key}
                            className={`nav-item ${activeNav === item.key ? 'active' : ''}`}
                            onClick={() => setActiveNav(item.key)}
                        >
                            {item.label}
                        </div>
                    ))}
                </nav>
            </aside>

            {/* Main content */}
            <div className="main-area">
                {/* Top bar */}
                <header className="topbar">
                    <div className="search-placeholder"></div>
                    <button className="quick-link-btn" onClick={handleLogout}>로그아웃</button>
                </header>

                {/* Content area */}
                <section className="content">
                    {activeNav === 'main' && (
                        <section className="hero">
                            <h2>어떤 프로젝트를 만들겠습니까?</h2>
                            <div className="hero-input">
                                <input type="text" placeholder="Describe an app or site you want to create…" />
                                <button className="start-btn">Start building</button>
                            </div>
                        </section>
                    )}
                    {activeNav === 'projects' && <div className="projects-page"><h2>프로젝트 목록</h2></div>}
                    {activeNav === 'vulnList' && <div className="vuln-list-page"><h2>취약점 정리</h2></div>}
                    {activeNav === 'vulnEdu' && <div className="vuln-edu-page"><h2>취약점 교육</h2></div>}
                    {activeNav === 'tos' && <div className="tos-page"><h2>개인정보 약관</h2></div>}
                </section>
            </div>
        </div>
    );
}
